package com.autoops.ai.service;import com.autoops.ai.provider.AIProvider;import com.autoops.ai.tool.AIToolRegistry;import org.springframework.core.io.ClassPathResource;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.util.*;@Service public class AIService{private final AIProvider provider;private final AIToolRegistry tools;private final String system;public AIService(AIProvider p,AIToolRegistry t){provider=p;tools=t;try{system=new String(new ClassPathResource("prompts/system/autoops-system.md").getInputStream().readAllBytes(),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException(e);}}public AIProvider.AIResponse chat(String text){return provider.chat(List.of(new AIProvider.Message("system",system),new AIProvider.Message("user",text)),List.of());}}
